package server

import (
	"encoding/json"
	"testing"
	"time"

	"github.com/Autumn-27/artex/db"
)

func TestInheritedDTOProvenance(t *testing.T) {
	createdAt := time.Date(2026, time.August, 19, 12, 0, 0, 0, time.UTC)
	node := &db.Node{
		ID:           41,
		Kind:         db.KindFinding,
		Payload:      json.RawMessage(`{"vulnclass":"xss","severity":"high","summary":"source finding"}`),
		State:        "confirmed",
		CreatedAt:    createdAt,
		SourceTaskID: 7,
		Inherited:    true,
	}

	nodeDTO := taskNodeDTO(node)
	if !nodeDTO.Inherited || nodeDTO.SourceTaskID != "7" {
		t.Fatalf("node provenance lost: %+v", nodeDTO)
	}
	finding := findingDTOsForOwner("7", "source", []*db.Node{node}, nil, nil)
	if len(finding) != 1 || !finding[0].Inherited || finding[0].SourceTaskID != "7" || finding[0].TaskID != "7" {
		t.Fatalf("finding provenance lost: %+v", finding)
	}

	intentID := int64(44)
	activity := activityDTO(db.Activity{
		ID:           45,
		NodeID:       &intentID,
		CreatedAt:    createdAt,
		SourceTaskID: 7,
		Inherited:    true,
	})
	if !activity.Inherited || activity.SourceTaskID != "7" || activity.IntentID != "44" {
		t.Fatalf("activity provenance lost: %+v", activity)
	}
	assetRef := coverageAssetRefDTO(db.AssetRef{
		ID: 46, Kind: db.KindFact, State: "confirmed", Summary: "source fact", SourceTaskID: 7, Inherited: true,
	})
	if !assetRef.Inherited || assetRef.SourceTaskID != "7" {
		t.Fatalf("asset ref provenance lost: %+v", assetRef)
	}
}

func TestInheritedIntentResultOnlyAllowsHistory(t *testing.T) {
	for _, state := range []string{"done", "blocked", "exhausted", "stopped"} {
		if !inheritedIntentResult(state) {
			t.Errorf("terminal state %q should be inherited history", state)
		}
	}
	for _, state := range []string{"open", "running", ""} {
		if inheritedIntentResult(state) {
			t.Errorf("live state %q must not enter inherited history", state)
		}
	}
}

func TestInheritedGraphSnapshotFiltersLiveIntentsAndEdges(t *testing.T) {
	nodes := []*db.Node{
		{ID: 1, Kind: db.KindFact, State: "confirmed"},
		{ID: 2, Kind: db.KindIntent, State: "running"},
		{ID: 3, Kind: db.KindIntent, State: "done"},
		{ID: 4, Kind: db.KindFinding, State: "confirmed"},
	}
	edges := []db.Edge{
		{From: 1, Rel: db.RelDerivedFrom, To: 2},
		{From: 1, Rel: db.RelDerivedFrom, To: 3},
		{From: 3, Rel: db.RelYields, To: 4},
	}

	gotNodes, gotEdges := inheritedGraphSnapshot(nodes, edges, 77)
	if len(gotNodes) != 3 {
		t.Fatalf("expected fact, terminal intent and finding; got %+v", gotNodes)
	}
	for _, node := range gotNodes {
		if node.ID == 2 {
			t.Fatal("running inherited intent leaked into graph snapshot")
		}
		if !node.Inherited || node.SourceTaskID != 77 {
			t.Fatalf("source provenance missing: %+v", node)
		}
	}
	if len(gotEdges) != 2 {
		t.Fatalf("edge referencing hidden live intent was not removed: %+v", gotEdges)
	}
	for _, edge := range gotEdges {
		if edge.From == 2 || edge.To == 2 {
			t.Fatalf("live intent id leaked through edge: %+v", edge)
		}
	}
}

func TestFindingProvenanceInTask(t *testing.T) {
	task := &Task{ID: "10", SourceTaskIDs: []int64{7, 8}}

	local := int64(10)
	if source, inherited, allowed := findingProvenanceInTask(task, &local); !allowed || inherited || source != "" {
		t.Fatalf("local finding: source=%q inherited=%v allowed=%v", source, inherited, allowed)
	}
	sourceID := int64(7)
	if source, inherited, allowed := findingProvenanceInTask(task, &sourceID); !allowed || !inherited || source != "7" {
		t.Fatalf("direct source finding: source=%q inherited=%v allowed=%v", source, inherited, allowed)
	}
	unrelated := int64(6)
	if _, _, allowed := findingProvenanceInTask(task, &unrelated); allowed {
		t.Fatal("unrelated finding must not be readable through task context")
	}
	if _, _, allowed := findingProvenanceInTask(task, nil); allowed {
		t.Fatal("detached finding must not be readable through task context")
	}
}

source/server/intent_intervention.go:
package server

import (
	"encoding/json"
	"errors"
	"net/http"
	"strconv"
	"strings"

	"github.com/Autumn-27/artex/db"
)

const maxWorkerMessageBytes = 64 << 10

func validWorkerMessageRequestID(id string) bool {
	if id == "" || len(id) > 128 {
		return false
	}
	for _, r := range id {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') ||
			(r >= '0' && r <= '9') || r == '-' || r == '_' || r == '.' || r == ':' {
			continue
		}
		return false
	}
	return true
}

// sendWorkerMessage continues a paused Worker intent with a human-authored message.
// The message is injected as the next turn's input through the same
// resume-from-transcript path the worker uses on a normal resume (ExecuteWithMessage),
// so this reuses the existing pause/resume machinery rather than a bespoke protocol.
// The run happens in a dedicated goroutine outside the worker pool (runDetachedIntent),
// so the message is picked up immediately even when every pool slot is busy — the same
// way the main-agent chat handler starts its run directly. In-memory only: a process
// restart re-runs the intent from its transcript without the message, which is
// acceptable for this rare interrupt-then-continue action.
func (s *Server) sendWorkerMessage(w http.ResponseWriter, r *http.Request) {
	t, ok := s.m.Task(r.PathValue("id"))
	if !ok {
		writeErr(w, http.StatusNotFound, "task not found")
		return
	}
	iid, err := strconv.ParseInt(r.PathValue("iid"), 10, 64)
	if err != nil || iid <= 0 {
		writeErr(w, http.StatusBadRequest, "bad intent id")
		return
	}
	r.Body = http.MaxBytesReader(w, r.Body, maxWorkerMessageBytes)
	var req struct {
		Message   string `json:"message"`
		RequestID string `json:"request_id"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		var tooLarge *http.MaxBytesError
		if errors.As(err, &tooLarge) {
			writeErr(w, http.StatusRequestEntityTooLarge, "Request body too large")
			return
		}
		writeErr(w, http.StatusBadRequest, "bad json: "+err.Error())
		return
	}
	message := strings.TrimSpace(req.Message)
	requestID := strings.TrimSpace(req.RequestID)
	if message == "" {
		writeErr(w, http.StatusBadRequest, "Message must not be empty")
		return
	}
	if len([]rune(message)) > 4000 {
		writeErr(w, http.StatusBadRequest, "Message must not exceed 4000 characters")
		return
	}
	if !validWorkerMessageRequestID(requestID) {
		writeErr(w, http.StatusBadRequest, "request_id must contain 1-128 letters, digits, -, _, . or :")
		return
	}

	// Reject non-runnable task lifecycles up front so the caller gets a clear reason
	// instead of a silent no-op. The intent itself must be paused: the UI flow is
	// interrupt (pause) first, then send.
	if s.engine.IsDeleting(t.ID) {
		writeErr(w, http.StatusConflict, "Task is being deleted; cannot send Worker messages")
		return
	}
	lifecycle := t.lifecycleSnapshot()
	switch {
	case lifecycle.Paused || s.engine.IsPaused(t.ID):
		writeErr(w, http.StatusConflict, "Task is paused; resume it before sending Worker messages")
		return
	case lifecycle.Queued:
		writeErr(w, http.StatusConflict, "Cannot send Worker messages to queued tasks")
		return
	case isTerminalStatus(lifecycle.Status):
		writeErr(w, http.StatusConflict, "Cannot send Worker messages to terminal tasks")
		return
	case s.engine.isSettling(t.ID):
		writeErr(w, http.StatusConflict, "Task is settling; cannot send Worker messages")
		return
	}

	node, err := t.Store.GetNode(iid)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, err.Error())
		return
	}
	if node == nil {
		if inherited, sourceErr := t.Store.GetNodeWithSources(iid); sourceErr == nil && inherited != nil && inherited.Inherited {
			writeErr(w, http.StatusConflict, "Inherited intents are read-only; cannot send Worker messages")
			return
		}
		writeErr(w, http.StatusNotFound, "intent not found")
		return
	}
	if node.Kind != db.KindIntent {
		writeErr(w, http.StatusConflict, "node is not an intent")
		return
	}
	if node.State != "paused" {
		writeErr(w, http.StatusConflict, "Only paused Workers can receive messages; pause the Worker first")
		return
	}
	agentMessage, ok := s.prepareChatMentionMessage(w, message)
	if !ok {
		return
	}

	// runDetachedIntent transitions paused->running, emits the user turn and starts a
	// dedicated run. Root the run at s.ctx so a disconnected browser cannot strand it
	// while task pause/delete/shutdown still stop it.
	if err := s.engine.runDetachedIntent(s.ctx, t, iid, requestID, message, agentMessage); err != nil {
		switch {
		case errors.Is(err, db.ErrIntentStateConflict):
			writeErr(w, http.StatusConflict, err.Error())
		default:
			writeErr(w, http.StatusInternalServerError, err.Error())
		}
		return
	}

	writeJSON(w, http.StatusOK, map[string]any{
		"id":         iid,
		"state":      "running",
		"accepted":   true,
		"request_id": requestID,
	})
}

