package server

import (
	"archive/zip"
	"bytes"
	"compress/bzip2"
	"fmt"
	"io"
	"path"
	"strings"
	"unicode/utf8"

	"github.com/klauspost/compress/zstd"
	"golang.org/x/text/encoding/simplifiedchinese"
)

// Go archive/zip only includes Store(0) and Deflate(8); other methods return
// "zip: unsupported compression algorithm". Nondefault archive settings often use other methods
// (7-Zip bzip2, WinZip zstd), so register the two supported pure-Go decompressors here.
// Unsupported formats (Deflate64 / LZMA / XZ / PPMd / encrypted archives) are rejected before
// extraction with a user-facing message rather than a raw low-level error.
const (
	zipMethodStore     = 0
	zipMethodDeflate   = 8
	zipMethodDeflate64 = 9
	zipMethodBzip2     = 12
	zipMethodLZMA      = 14
	zipMethodZstdPKW   = 20 // Early PKWARE method number assigned to zstd
	zipMethodZstd      = 93
	zipMethodXZ        = 95
	zipMethodJPEG      = 96
	zipMethodWavPack   = 97
	zipMethodPPMd      = 98
	zipMethodAES       = 99
)

var zipMethodNames = map[uint16]string{
	zipMethodStore:     "Store",
	zipMethodDeflate:   "Deflate",
	zipMethodDeflate64: "Deflate64",
	zipMethodBzip2:     "bzip2",
	zipMethodLZMA:      "LZMA",
	zipMethodZstdPKW:   "Zstandard",
	zipMethodZstd:      "Zstandard",
	zipMethodXZ:        "XZ",
	zipMethodJPEG:      "JPEG",
	zipMethodWavPack:   "WavPack",
	zipMethodPPMd:      "PPMd",
	zipMethodAES:       "AES encryption",
}

func zipMethodName(m uint16) string {
	if n, ok := zipMethodNames[m]; ok {
		return n
	}
	return "Unknown"
}

// newSkillZipReader parses an uploaded archive and registers the extra decompressors
// we can support beyond the stdlib's Store/Deflate.
func newSkillZipReader(buf []byte) (*zip.Reader, error) {
	zr, err := zip.NewReader(bytes.NewReader(buf), int64(len(buf)))
	if err != nil {
		return nil, fmt.Errorf("Cannot parse archive (ZIP format required): %w", err)
	}
	zr.RegisterDecompressor(zipMethodBzip2, func(r io.Reader) io.ReadCloser {
		return io.NopCloser(bzip2.NewReader(r))
	})
	zdec := zstd.ZipDecompressor(zstd.WithDecoderConcurrency(1))
	zr.RegisterDecompressor(zipMethodZstd, zdec)
	zr.RegisterDecompressor(zipMethodZstdPKW, zdec)
	return zr, nil
}

// skillZipEntry pairs a zip entry with its decoded (UTF-8) name — f.Name may hold
// raw GBK bytes, see zipEntryName.
type skillZipEntry struct {
	f    *zip.File
	name string
}

// skillZipEntries lists the archive's real files (no directory entries, no archiver
// junk) with their names decoded to UTF-8.
func skillZipEntries(zr *zip.Reader) []skillZipEntry {
	out := make([]skillZipEntry, 0, len(zr.File))
	for _, f := range zr.File {
		if f.FileInfo().IsDir() {
			continue
		}
		name := zipEntryName(f)
		if strings.HasPrefix(name, "__MACOSX/") || strings.Contains(name, "/__MACOSX/") ||
			path.Base(name) == ".DS_Store" {
			continue // macOS packaging metadata
		}
		out = append(out, skillZipEntry{f: f, name: name})
	}
	return out
}

// zipEntryName returns the entry path as UTF-8. Windows 7-Zip / WinRAR / Explorer may
// write Chinese filenames as GBK without the UTF-8 flag. Go preserves those bytes, which
// are not valid UTF-8 and fail path validation; fall back to GBK decoding here.
func zipEntryName(f *zip.File) string {
	if utf8.ValidString(f.Name) {
		return f.Name
	}
	if dec, err := simplifiedchinese.GBK.NewDecoder().String(f.Name); err == nil && utf8.ValidString(dec) {
		return dec
	}
	return f.Name
}

// checkSkillZipMethods rejects archives we cannot extract, naming the offending
// entry and method instead of letting f.Open() fail with an opaque English error.
func checkSkillZipMethods(entries []skillZipEntry) error {
	for _, e := range entries {
		if e.f.Flags&0x1 != 0 || e.f.Method == zipMethodAES {
			return fmt.Errorf("Archive is encrypted (%s); upload an unencrypted ZIP", e.name)
		}
		switch e.f.Method {
		case zipMethodStore, zipMethodDeflate, zipMethodBzip2, zipMethodZstd, zipMethodZstdPKW:
		default:
			return fmt.Errorf("Archive uses unsupported compression %s (method %d): %s. "+
				"Repackage using Store or Deflate (select Deflate in 7-Zip/WinRAR, "+
				"or use your system's Compress/Send to compressed folder option, or zip -r)",
				zipMethodName(e.f.Method), e.f.Method, e.name)
		}
	}
	return nil
}

source/server/static_files.go:
package server

import (
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/hex"
	"io/fs"
	"mime"
	"net/http"
	"path"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/andybalholm/brotli"
)

// staticFileServer serves files out of an io/fs.FS (normally the embedded
// frontend) with the two things http.ServeFileFS cannot provide for an
// embed.FS:
//
//   - compression. An embed.FS response otherwise ships the raw bytes even
//     when the browser advertises gzip/br. The exported Next.js UI is several
//     megabytes of JavaScript, so on a remote link the browser's six
//     connections per host stall and complete together — which looks like the
//     UI timing out after every click.
//   - caching. embed.FS entries have a zero ModTime, so ServeContent emits no
//     Last-Modified and no ETag. Without an ETag every navigation re-downloads
//     the whole bundle.
//
// Compressed bodies are computed once and cached in memory. Files are only
// compressed when the client asks for it, the type is textual, the response is
// a full 200 (not a Range or HEAD range request), and the body is worth it.
type staticFileServer struct {
	fsys  fs.FS
	cache sync.Map // name -> *staticAsset
}

type staticAsset struct {
	raw         []byte
	etag        string
	contentType string

	gzipOnce sync.Once
	gzipBody []byte
	brOnce   sync.Once
	brBody   []byte
}

func newStaticFileServer(fsys fs.FS) *staticFileServer {
	return &staticFileServer{fsys: fsys}
}

// serveFileIfExists serves name when it is a regular file in the fs, reporting
// whether it did. Existence is checked through the content cache so a request
// for a missing path costs one failed fs read.
func (s *staticFileServer) serveFileIfExists(w http.ResponseWriter, r *http.Request, name string) bool {
	a, ok := s.load(name)
	if !ok {
		return false
	}
	s.serve(w, r, a)
	return true
}

func (s *staticFileServer) load(name string) (*staticAsset, bool) {
	if v, ok := s.cache.Load(name); ok {
		return v.(*staticAsset), true
	}
	data, err := fs.ReadFile(s.fsys, name)
	if err != nil || data == nil {
		return nil, false
	}
	sum := sha256.Sum256(data)
	a := &staticAsset{
		raw:         data,
		etag:        `"` + hex.EncodeToString(sum[:16]) + `"`,
		contentType: staticContentType(name),
	}
	actual, _ := s.cache.LoadOrStore(name, a)
	return actual.(*staticAsset), true
}

func (s *staticFileServer) serve(w http.ResponseWriter, r *http.Request, a *staticAsset) {
	h := w.Header()
	h.Set("Content-Type", a.contentType)
	h.Set("ETag", a.etag)
	h.Set("X-Content-Type-Options", "nosniff")
	h.Set("Vary", "Accept-Encoding")
	h.Set("Cache-Control", staticCacheControl(r.URL.Path))

	// Unconditional revalidation: a matching ETag means the browser already has
	// the exact bytes, including for the content-hashed immutable assets (which
	// normally never reach this branch).
	if etagMatches(r.Header.Get("If-None-Match"), a.etag) {
		w.WriteHeader(http.StatusNotModified)
		return
	}

	// Range requests must not be compressed and need the standard partial-content
	// handling. ServeContent also applies our ETag/Content-Type headers.
	if r.Header.Get("Range") != "" {
		http.ServeContent(w, r, path.Base(r.URL.Path), time.Time{}, bytes.NewReader(a.raw))
		return
	}

	body := a.raw
	if enc := negotiateEncoding(r, a); enc != "" {
		if enc == "br" {
			a.brOnce.Do(func() { a.brBody = brotliCompress(a.raw) })
			body = a.brBody
		} else {
			a.gzipOnce.Do(func() { a.gzipBody = gzipCompress(a.raw) })
			body = a.gzipBody
		}
		h.Set("Content-Encoding", enc)
	}
	h.Set("Content-Length", strconv.Itoa(len(body)))
	if r.Method == http.MethodHead {
		w.WriteHeader(http.StatusOK)
		return
	}
	if _, err := w.Write(body); err != nil {
		return
	}
}

// staticCacheControl marks the content-hashed Next.js build tree immutable and
// makes everything else revalidate. HTML and RSC payloads must revalidate so a
// rebuilt binary is picked up after an upgrade; the ETag keeps that cheap.
func staticCacheControl(urlPath string) string {
	if strings.HasPrefix(urlPath, "/_next/static/") {
		return "public, max-age=31536000, immutable"
	}
	return "no-cache"
}

// negotiateEncoding returns "br" or "gzip" when the request accepts one and the
// asset is worth compressing, otherwise "".
func negotiateEncoding(r *http.Request, a *staticAsset) string {
	if r.Method == http.MethodHead || len(a.raw) < 1024 || !isCompressible(a.contentType) {
		return ""
	}
	ae := r.Header.Get("Accept-Encoding")
	// Prefer brotli; brotli-5 compresses the UI better than gzip for similar CPU.
	if acceptsEncoding(ae, "br") {
		return "br"
	}
	if acceptsEncoding(ae, "gzip") {
		return "gzip"
	}
	return ""
}

// acceptsEncoding reports whether name is acceptable per an Accept-Encoding
// header. It understands q-values well enough to reject explicit q=0.
func acceptsEncoding(header, name string) bool {
	for _, part := range strings.Split(header, ",") {
		fields := strings.Split(part, ";")
		if !strings.EqualFold(strings.TrimSpace(fields[0]), name) {
			continue
		}
		for _, p := range fields[1:] {
			p = strings.TrimSpace(p)
			if !strings.HasPrefix(p, "q=") {
				continue
			}
			if q := strings.TrimPrefix(p, "q="); q == "0" || strings.HasPrefix(q, "0.") && strings.Trim(q[2:], "0") == "" {
				return false
			}
		}
		return true
	}
	return false
}

func isCompressible(contentType string) bool {
	ct := strings.ToLower(contentType)
	if strings.HasPrefix(ct, "text/") {
		// SSE is an endless stream: compressing it buffers frames and breaks the UI.
		return !strings.HasPrefix(ct, "text/event-stream")
	}
	switch {
	case strings.Contains(ct, "javascript"),
		strings.Contains(ct, "json"),
		strings.Contains(ct, "xml"),
		strings.Contains(ct, "svg"),
		strings.Contains(ct, "wasm"):
		return true
	}
	return false
}

func gzipCompress(src []byte) []byte {
	var buf bytes.Buffer
	// BestSpeed is the right trade-off for on-demand per-file compression: the
	// UI chunks are large but the cache means each is compressed once.
	zw, _ := gzip.NewWriterLevel(&buf, gzip.BestSpeed)
	_, _ = zw.Write(src)
	_ = zw.Close()
	return buf.Bytes()
}

func brotliCompress(src []byte) []byte {
	var buf bytes.Buffer
	zw := brotli.NewWriterLevel(&buf, 5)
	_, _ = zw.Write(src)
	_ = zw.Close()
	return buf.Bytes()
}

func etagMatches(header, etag string) bool {
	if header == "" {
		return false
	}
	for _, part := range strings.Split(header, ",") {
		part = strings.TrimSpace(part)
		if part == "*" || part == etag || strings.TrimPrefix(part, "W/") == etag {
			return true
		}
	}
	return false
}

// staticContentType fixes the content types we rely on rather than depending on
// the host's mime.types database (which differs between Linux and macOS and can
// make a binary behave differently in the image and on a developer machine).
func staticContentType(name string) string {
	switch ext := strings.ToLower(path.Ext(name)); ext {
	case ".html":
		return "text/html; charset=utf-8"
	case ".js", ".mjs":
		return "text/javascript; charset=utf-8"
	case ".css":
		return "text/css; charset=utf-8"
	case ".json", ".map":
		return "application/json"
	case ".txt":
		return "text/plain; charset=utf-8"
	case ".svg":
		return "image/svg+xml"
	case ".png":
		return "image/png"
	case ".jpg", ".jpeg":
		return "image/jpeg"
	case ".gif":
		return "image/gif"
	case ".webp":
		return "image/webp"
	case ".avif":
		return "image/avif"
	case ".ico":
		return "image/x-icon"
	case ".woff":
		return "font/woff"
	case ".woff2":
		return "font/woff2"
	case ".ttf":
		return "font/ttf"
	case ".otf":
		return "font/otf"
	case ".wasm":
		return "application/wasm"
	case ".xml":
		return "application/xml"
	case ".webmanifest":
		return "application/manifest+json"
	case ".pdf":
		return "application/pdf"
	}
	if ct := mime.TypeByExtension(path.Ext(name)); ct != "" {
		return ct
	}
	return "application/octet-stream"
}

source/server/static_files_test.go:
package server

import (
	"bytes"
	"compress/gzip"
	"io"
	"net/http"
	"net/http/httptest"
	"strconv"
	"strings"
	"testing"
	"testing/fstest"

	"github.com/andybalholm/brotli"
)

// testStaticFS returns a tiny frontend tree: a compressible chunk under the
// content-hashed _next/static tree, an already-compressed image, and an HTML
// document that must revalidate.
func testStaticFS() fstest.MapFS {
	js := strings.Repeat("export const value = 1;\n", 200) // > 1 KB
	return fstest.MapFS{
		"_next/static/chunks/app.js":  {Data: []byte(js)},
		"_next/static/media/logo.png": {Data: bytes.Repeat([]byte{0x89, 0x50, 0x4e, 0x47}, 600)},
		"index.html":                  {Data: []byte("<html><body>artex</body></html>")},
		"_next/static/chunks/tiny.js": {Data: []byte("x")},
	}
}

func serveTest(t *testing.T, fss *staticFileServer, name, method string, headers map[string]string) *httptest.ResponseRecorder {
	t.Helper()
	r := httptest.NewRequest(method, "/"+name, nil)
	for k, v := range headers {
		r.Header.Set(k, v)
	}
	w := httptest.NewRecorder()
	if ok := fss.serveFileIfExists(w, r, name); !ok {
		t.Fatalf("serveFileIfExists(%q) = false, want true", name)
	}
	return w
}

func TestStaticServesBrotliWhenAccepted(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	w := serveTest(t, fss, "_next/static/chunks/app.js", http.MethodGet, map[string]string{"Accept-Encoding": "gzip, br"})

	if got := w.Header().Get("Content-Encoding"); got != "br" {
		t.Fatalf("Content-Encoding = %q, want br", got)
	}
	if got := w.Header().Get("Content-Length"); got != strconv.Itoa(w.Body.Len()) {
		t.Fatalf("Content-Length = %q, body = %d", got, w.Body.Len())
	}
	decoded, err := io.ReadAll(brotli.NewReader(bytes.NewReader(w.Body.Bytes())))
	if err != nil {
		t.Fatalf("brotli decode: %v", err)
	}
	if got, want := string(decoded), string(testStaticFS()["_next/static/chunks/app.js"].Data); got != want {
		t.Fatalf("decoded body mismatch: got %d bytes, want %d", len(got), len(want))
	}
	if w.Body.Len() >= len(testStaticFS()["_next/static/chunks/app.js"].Data) {
		t.Fatalf("compressed size %d is not smaller than raw %d", w.Body.Len(), len(testStaticFS()["_next/static/chunks/app.js"].Data))
	}
}

func TestStaticGzipFallback(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	w := serveTest(t, fss, "_next/static/chunks/app.js", http.MethodGet, map[string]string{"Accept-Encoding": "gzip"})

	if got := w.Header().Get("Content-Encoding"); got != "gzip" {
		t.Fatalf("Content-Encoding = %q, want gzip", got)
	}
	zr, err := gzip.NewReader(bytes.NewReader(w.Body.Bytes()))
	if err != nil {
		t.Fatalf("gzip reader: %v", err)
	}
	decoded, err := io.ReadAll(zr)
	if err != nil {
		t.Fatalf("gzip decode: %v", err)
	}
	if len(decoded) != len(testStaticFS()["_next/static/chunks/app.js"].Data) {
		t.Fatalf("decoded %d bytes, want %d", len(decoded), len(testStaticFS()["_next/static/chunks/app.js"].Data))
	}
}

func TestStaticDoesNotCompressWhenNotAcceptedOrNotWorthIt(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	cases := []struct {
		name    string
		headers map[string]string
	}{
		{"_next/static/chunks/app.js", map[string]string{"Accept-Encoding": "identity"}},
		{"_next/static/chunks/app.js", map[string]string{"Accept-Encoding": "br;q=0, gzip;q=0"}},
		{"_next/static/media/logo.png", map[string]string{"Accept-Encoding": "br, gzip"}},
		{"_next/static/chunks/tiny.js", map[string]string{"Accept-Encoding": "br, gzip"}},
	}
	for _, tc := range cases {
		w := serveTest(t, fss, tc.name, http.MethodGet, tc.headers)
		if got := w.Header().Get("Content-Encoding"); got != "" {
			t.Errorf("%s %v: Content-Encoding = %q, want none", tc.name, tc.headers, got)
		}
	}
}

func TestStaticCacheControl(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	w := serveTest(t, fss, "_next/static/chunks/app.js", http.MethodGet, nil)
	if got, want := w.Header().Get("Cache-Control"), "public, max-age=31536000, immutable"; got != want {
		t.Fatalf("hashed asset Cache-Control = %q, want %q", got, want)
	}
	html := serveTest(t, fss, "index.html", http.MethodGet, nil)
	if got, want := html.Header().Get("Cache-Control"), "no-cache"; got != want {
		t.Fatalf("html Cache-Control = %q, want %q", got, want)
	}
}

func TestStaticETagRevalidation(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	first := serveTest(t, fss, "_next/static/chunks/app.js", http.MethodGet, nil)
	etag := first.Header().Get("ETag")
	if etag == "" {
		t.Fatal("missing ETag")
	}
	second := serveTest(t, fss, "_next/static/chunks/app.js", http.MethodGet, map[string]string{"If-None-Match": etag})
	if second.Code != http.StatusNotModified {
		t.Fatalf("status = %d, want 304", second.Code)
	}
	if second.Body.Len() != 0 {
		t.Fatalf("304 body = %d bytes, want 0", second.Body.Len())
	}
}

func TestStaticRangeBypassesCompression(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	w := serveTest(t, fss, "_next/static/chunks/app.js", http.MethodGet, map[string]string{
		"Accept-Encoding": "br, gzip",
		"Range":           "bytes=0-9",
	})
	if w.Code != http.StatusPartialContent {
		t.Fatalf("status = %d, want 206", w.Code)
	}
	if got := w.Header().Get("Content-Encoding"); got != "" {
		t.Fatalf("Content-Encoding = %q, want none for range", got)
	}
	if w.Body.Len() != 10 {
		t.Fatalf("range body = %d bytes, want 10", w.Body.Len())
	}
}

func TestStaticHeadHasNoBody(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	w := serveTest(t, fss, "_next/static/chunks/app.js", http.MethodHead, map[string]string{"Accept-Encoding": "br"})
	if w.Body.Len() != 0 {
		t.Fatalf("HEAD body = %d bytes, want 0", w.Body.Len())
	}
	if w.Header().Get("Content-Length") == "" {
		t.Fatal("HEAD missing Content-Length")
	}
}

func TestStaticMissingFile(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	r := httptest.NewRequest(http.MethodGet, "/nope.js", nil)
	w := httptest.NewRecorder()
	if fss.serveFileIfExists(w, r, "nope.js") {
		t.Fatal("served a missing file")
	}
}

func TestCompressionCachesBodies(t *testing.T) {
	fss := newStaticFileServer(testStaticFS())
	serveTest(t, fss, "_next/static/chunks/app.js", http.MethodGet, map[string]string{"Accept-Encoding": "br"})
	a, ok := fss.load("_next/static/chunks/app.js")
	if !ok || len(a.brBody) == 0 {
		t.Fatal("brotli body was not cached")
	}
	first := a.brBody
	serveTest(t, fss, "_next/static/chunks/app.js", http.MethodGet, map[string]string{"Accept-Encoding": "br"})
	if &first[0] != &a.brBody[0] {
		t.Fatal("compressed body was recomputed")
	}
}

